        DROP TRIGGER IF EXISTS "_outbox_capture" ON "WhatsAppTemplate";
        CREATE TRIGGER "_outbox_capture" AFTER INSERT OR UPDATE ON "WhatsAppTemplate"
            FOR EACH ROW EXECUTE FUNCTION _outbox_capture('kind');
    END IF;
END $$;
